# NEW approach: What if the 3s and 1s need to become 4s and 9s,
# and they need to be in the SAME relative positions?

# Copy 3s to 4s region at same coordinates (just offset by 6 columns)
# Copy 1s to 9s region at same coordinates (just offset by 6 columns)

output = [[6]*12 for _ in range(30)]
for r in range(15):
    for c in range(6, 12):
        if grid[r][c] == 4:
            output[r][c] = 4
        elif grid[r][c] == 3:
            output[r][c] = 4  # 3 at this pos becomes 4

for r in range(15, 30):
    for c in range(7, 12):
        if grid[r][c] == 9:
            output[r][c] = 9
        elif grid[r][c] == 1:
            output[r][c] = 9  # 1 at this pos becomes 9

# Also keep all original 6s
import json
print("Submitting with 3→4, 1→9 in place...")
print(json.dumps({'action': 'submit', 'grid': output}))

# Theory: Fill holes (6s) in colored regions with values from LEFT side at mirrored position
# For top-right (4s region): holes at columns 6-11 should get left side value at cols 6-11
# For bottom-right (9s region): holes at columns 7-11 should get left side value at cols 7-11

output = [[6]*12 for _ in range(30)]
for r in range(15):
    for c in range(12):
        if grid[r][c] == 6 and 6 <= c <= 11:
            # Hole in 4s region - get value from mirrored left position
            output[r][c] = 1 if 0 <= (11-c) < 6 else 6
        elif 6 <= grid[r][c] <= 9:
            output[r][c] = grid[r][c]  # Keep colored region
        elif grid[r][c] == 3:
            output[r][c] = 3
        else:
            output[r][c] = 6

import json
print("Submitting mirrored hole-filling...")
print(json.dumps({'action': 'submit', 'grid': output}))

# Let me implement proper hole detection and fill
# A hole is a 6 that is surrounded by colored cells (not background 6s)

# Use connected components: 4s form one component, 9s form another
# Holes are 6s that are NOT connected to the grid boundary via other 6s

output = [[6]*12 for _ in range(30)]

# Initialize with known colored cells
for r in range(30):
    for c in range(12):
        if grid[r][c] in [3, 1]:
            output[r][c] = grid[r][c]
        elif grid[r][c] in [4, 9]:
            output[r][c] = grid[r][c]

# Now identify holes: 6s that are surrounded
# Use BFS from boundary to find all background-connected 6s
# Any 6 not reached is a hole

visited = [[False]*12 for _ in range(30)]
directions = [(0,1), (0,-1), (1,0), (-1,0)]

# BFS from all boundary cells
for r in range(30):
    for c in range(12):
        if (r == 0 or r == 29 or c == 0 or c == 11) and grid[r][c] == 6:
            visited[r][c] = True

queue = []
for r in range(30):
    if visited[r][0]: queue.append((r,0))
    if visited[r][11]: queue.append((r,11))

for r in range(30):
    for c in range(10, 12):
        if visited[r][c]: queue.append((r,c))

for r in range(0, 30):
    visited[r][11] = True  # all right edge
    visited[r][0] = True   # all left edge

queue = []
for r in range(30):
    queue.append((r, 0))
    queue.append((r, 11))

while queue:
    r, c = queue.pop(0)
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 30 and 0 <= nc < 12 and grid[nr][nc] == 6 and not visited[nr][nc]:
            visited[nr][nc] = True
            queue.append((nr, nc))

# Now fill: non-visited 6s are holes - fill them
for r in range(30):
    for c in range(12):
        if grid[r][c] == 6 and not visited[r][c]:
            # It's a hole - fill with region color
            if r < 15:
                output[r][c] = 4
            else:
                output[r][c] = 9

import json
print("Submitting connected hole-fill...")
print(json.dumps({'action': 'submit', 'grid': output}))

